import {
  WixDataItem,
  WixDataBulkResult,
  WixDataAsyncByFilterOptions,
  WixDataAsyncJob,
  WixDataFilterInput,
} from './types'
import { FieldModificationsBuilder } from './WixDataFieldModificationsBuilder'

export interface WixDataPatchOptions {
  /**
   * Prevents hooks from running for the operation. Can only be used in the [backend code of a Wix site](https://dev.wix.com/docs/develop-websites/articles/coding-with-velo/backend-code/about-the-site-backend).
   *
   * Default: `false`.
   */
  suppressHooks?: boolean

  /**
   * When `true`, operations include draft items. Read operations include draft items in their response, and write operations modify draft items.
   *
   * Default: `false`.
   */
  showDrafts?: boolean

  /**
   * If provided, item will be patched only if condition is met.
   */
  condition?: WixDataFilterInput
}

export interface WixDataBulkPatchOptions {
  /**
   * Prevents hooks from running for the operation. Can only be used in the [backend code of a Wix site](https://dev.wix.com/docs/develop-websites/articles/coding-with-velo/backend-code/about-the-site-backend).
   *
   * Default: `false`.
   */
  suppressHooks?: boolean

  /**
   * When `true`, operations include draft items. Read operations include draft items in their response, and write operations modify draft items.
   *
   * Default: `false`.
   * @internal
   */
  showDrafts?: boolean

  /**
   * If provided, only items matching condition will be patched.
   */
  condition?: WixDataFilterInput
}

/**
 * @builder
 */
export interface WixDataBulkPatch
  extends FieldModificationsBuilder<WixDataBulkPatch> {
  /**
   * Runs the bulk patch operation and returns a Promise that resolves to information about the results.
   *
   * @public
   * @documentationMaturity preview
   * @returns Bulk operation results.
   */
  run(options?: WixDataBulkPatchOptions): Promise<WixDataBulkResult>
}

/**
 * @builder
 */
export interface WixDataPatchByFilter
  extends FieldModificationsBuilder<WixDataPatchByFilter> {
  /**
   * Starts the async patch operation and returns a Promise that resolves to the async job.
   *
   * @public
   * @documentationMaturity preview
   * @returns Async job information.
   */
  run(options?: WixDataAsyncByFilterOptions): Promise<WixDataAsyncJob>
}

/**
 * @builder
 */
export interface WixDataPatch extends FieldModificationsBuilder<WixDataPatch> {
  /**
   * Runs the patch operation and returns a Promise that resolves to the patched item and operation metadata.
   *
   * @public
   * @documentationMaturity preview
   * @returns Modified data item.
   */

  run(options?: WixDataPatchOptions): Promise<WixDataItem>
}
